import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 12 — Pull Requests & Agent Code","description":"","frontmatter":{"source":"weeks/12-pull-requests/README.md"},"headers":[],"relativePath":"weeks/12-pull-requests/index.md","filePath":"weeks/12-pull-requests/index.md"}'),s={name:"weeks/12-pull-requests/index.md"};function n(i,e,l,h,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-12--pull-requests--agent-code" tabindex="-1">Week 12 — Pull Requests &amp; Agent Code <a class="header-anchor" href="#week-12--pull-requests--agent-code" aria-label="Permalink to &quot;Week 12 — Pull Requests &amp; Agent Code&quot;">​</a></h1><blockquote><p>Agent code is almost right. Every change joins <code>main</code> through a pull request you have read, tested and can explain.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (about 30 min)</td><td>Read this page and skim <a href="./../../resources/git-cheatsheet.html#branches-and-pull-requests">Branches and pull requests</a> in the Git Cheat Sheet. Check that your week 11 feature is on GitHub (<a href="#before-class">Before class</a>)</td></tr><tr><td><strong>Studio A</strong></td><td>Talk: branches, pull requests, reviewing agent code, testing your <code>AGENTS.md</code> · live demo: a pull request from branch to merge · add one test by hand (🔴 AI off), then open, review and merge your first pull request · checkpoint share</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell · <strong>find the bug planted in agent-written code</strong> (🔴 AI off) · <strong>feature clinic:</strong> a simple chart or an external API · project time and help · exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong></td><td>Default 11:59 pm the night before. <strong>Milestone 1</strong> (<a href="./../../projects/capstone.html#milestones">capstone milestones</a>, copied in <a href="./homework.html#milestone-1">Week 12 Homework — Milestone 1: a walking skeleton: Milestone 1</a>): <code>SPEC.md</code> complete with a Goldfish test · <code>AGENTS.md</code> with Scope and trial notes · two features merged through pull requests, each with a test written first · production URL and screenshot on Canvas · <code>PROMPTS.md</code> with teach-backs. Also your reflection on Canvas (🔴 AI off)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: agent mode for features and the <code>AGENTS.md</code> trial, approvals on (never autopilot or skip-permissions modes); Ask mode to explain code · 🟡 AI limited: new criteria in <code>SPEC.md</code> (you write them), the Goldfish test · 🔴 AI off: the test you write by hand, the planted-bug hunt (for the Fixer), teach-backs, trial notes, the reflection, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>README (this page), <a href="./lab.html">Week 12 Lab — Pull requests and agent code</a>, <a href="./homework.html">Week 12 Homework — Milestone 1: a walking skeleton</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../projects/capstone.html">Capstone brief</a> · <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">capstone starter: feature patterns</a> · <a href="./../../resources/git-cheatsheet.html">Git Cheat Sheet</a> · <a href="./../../resources/troubleshooting.html#i-have-a-merge-conflict">I have a merge conflict</a> · <a href="./../../resources/without-ai-skills.html">Six skills you must show without AI</a> · <a href="./../../TOOLS.html#credits-budget-for-the-course">Tool Handout: credits</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your capstone runs at its production URL, and two features are merged through pull requests. Week 13 Studio A connects your capstone to a database, and week 14 Studio B reviews one of your pull requests</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h: prep 30 min, homework about 5 h (including project time), <code>PROMPTS.md</code> and the reflection about 30 min</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system: your reflection and submission links go there. Your code and project documents stay in your public repository.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Put work on a <strong>branch</strong>, open a <strong>pull request</strong>, review its diff as a reviewer would, and merge it.</li><li>Find and fix a bug in agent-written code by hand, starting from the test output.</li><li>Refuse to &quot;fix&quot; a failing test by changing what it expects, and spot an agent that does.</li><li>Add a chart or an external-API feature with check-first tests, using a fake <code>fetch</code> for the API.</li><li>Test whether an agent actually follows your <code>AGENTS.md</code>, and improve the file from the evidence.</li><li>Explain agent-written code with the AI off.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your <code>feature/ac1</code> branch is on GitHub (the branch menu on your repository page lists it), with a test that failed first and passes now.</li><li>☐ Your <code>PROMPTS.md</code> has a teach-back for that feature. Re-read it: is it still accurate?</li><li>☐ Check your credits. This week&#39;s homework runs two agent tasks and a second feature.</li><li>☐ Not deployed yet? Do <a href="./../11-agents/homework.html#4-deploy-on-day-one-about-30-min">week 11&#39;s deploy task</a> first: your pull request then gets a preview link.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-12.html" target="_blank" rel="noreferrer">slides</a>) · live demo · <a href="./lab.html#studio-a--your-first-pull-request-75-min">lab</a>: a test by hand, then your first pull request, reviewed and merged · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · <a href="./lab.html#studio-b--agent-code-under-the-microscope-75-min">lab</a>: the planted-bug hunt, the feature clinic · project time and help · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-12.html" target="_blank" rel="noreferrer">Slides</a>, <a href="./lab.html">lab</a> and <a href="./homework.html">homework</a></li><li><a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">Capstone starter: feature patterns</a>: a chart helper and an external-API route, both tested</li><li>Templates: <a href="./../../templates/PROMPTS.html">PROMPTS.md template</a>, <a href="./../../templates/TESTS.html">TESTS.md template</a>, <a href="./../../templates/AGENTS.html">AGENTS.md template</a></li><li>Glossary: <a href="./../../resources/glossary.html#branch">branch</a>, <a href="./../../resources/glossary.html#pull-request">pull request</a>, <a href="./../../resources/glossary.html#merge">merge</a>, <a href="./../../resources/glossary.html#diff">diff</a>, <a href="./../../resources/glossary.html#github-actions">GitHub Actions</a>, <a href="./../../resources/glossary.html#preview-deployment">preview deployment</a>, <a href="./../../resources/glossary.html#mock">mock</a>, <a href="./../../resources/glossary.html#goldfish-test">Goldfish test</a></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>.</p><h3 id="branches-keep-main-safe" tabindex="-1">Branches keep <code>main</code> safe <a class="header-anchor" href="#branches-keep-main-safe" aria-label="Permalink to &quot;Branches keep `main` safe&quot;">​</a></h3><p>A <strong>branch</strong> is a separate line of work. <code>main</code> is the version that&#39;s deployed, so it should always work; each feature grows on its own branch, started from an up-to-date <code>main</code>, and if it goes wrong, <code>main</code> is untouched.</p><h3 id="a-pull-request-is-a-place-to-read" tabindex="-1">A pull request is a place to read <a class="header-anchor" href="#a-pull-request-is-a-place-to-read" aria-label="Permalink to &quot;A pull request is a place to read&quot;">​</a></h3><p>A <strong>pull request</strong> (PR) asks to <strong>merge</strong> a branch into <code>main</code>. It shows the whole change as one <strong>diff</strong>, runs your tests on it (the check comes from GitHub Actions), and, once your capstone is on Vercel, links to a preview of it. Review your own pull request as if a stranger wrote it: only the files you meant to change, no secrets, every line one you can explain, tests changed only where you added one.</p><h3 id="agent-code-is-almost-right" tabindex="-1">Agent code is almost right <a class="header-anchor" href="#agent-code-is-almost-right" aria-label="Permalink to &quot;Agent code is almost right&quot;">​</a></h3><p>In one study of 917 students, bugs planted in otherwise-correct AI code led students to fix the code themselves instead of asking the AI again, and they did better on their next attempt (<a href="https://arxiv.org/pdf/2607.05068" target="_blank" rel="noreferrer">Pădurean et al.</a>). So a classmate plants a bug in <em>your</em> agent&#39;s code, and you find it with the AI off, starting from the test output.</p><h3 id="watch-the-tests-too" tabindex="-1">Watch the tests, too <a class="header-anchor" href="#watch-the-tests-too" aria-label="Permalink to &quot;Watch the tests, too&quot;">​</a></h3><p>Never fix a failing test by changing what it expects, unless <code>SPEC.md</code> says the test is wrong. One developer&#39;s &quot;fix it&quot; prompt changed a test&#39;s expected status from 200 to 500, so the test passed and the bug stayed (<a href="https://news.ycombinator.com/item?id=48662310" target="_blank" rel="noreferrer">HN discussion</a>). In a pull request, look at what changed in <code>tests/</code>.</p><h3 id="test-your-instructions" tabindex="-1">Test your instructions <a class="header-anchor" href="#test-your-instructions" aria-label="Permalink to &quot;Test your instructions&quot;">​</a></h3><p>Your <code>AGENTS.md</code> is advice. The <strong>AGENTS.md trial</strong> finds out how much of it the agent takes: two small tasks, one a probe that tempts the agent to break a rule. If it ignored a line, the trial worked: you improve the file and name the rail (an approval prompt, the Codespace, a save point) that would have protected you.</p><h3 id="two-new-feature-patterns" tabindex="-1">Two new feature patterns <a class="header-anchor" href="#two-new-feature-patterns" aria-label="Permalink to &quot;Two new feature patterns&quot;">​</a></h3><p>For <strong>a chart</strong>, most bugs are data bugs, so you test the function that turns your records into <code>{ label, value }</code> rows. For <strong>an external public API</strong>, the tests replace <code>fetch</code> with a fake (a <strong>mock</strong>), so they run offline and cover a good answer, a failure or timeout, and bad input. The capstone starter has a tested example of each.</p><h3 id="milestone-1-a-walking-skeleton" tabindex="-1">Milestone 1: a walking skeleton <a class="header-anchor" href="#milestone-1-a-walking-skeleton" aria-label="Permalink to &quot;Milestone 1: a walking skeleton&quot;">​</a></h3><p>By the end of the week: a spec that passed a Goldfish test, an <code>AGENTS.md</code> you&#39;ve tested, two features merged through pull requests, and a working production URL.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li>The week 12 exit ticket (🔴 AI off) at the end of Studio B, including one question about your week 10 deployment. Graded on completion, not correctness.</li><li>Two lab tasks practice <a href="./../../resources/without-ai-skills.html">skills you must show without AI</a>: in Studio A you write a criterion and its test by hand, and in Studio B you find a bug planted in your own agent&#39;s code, starting from the test output.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5 hours, including project time. Details and the checklist are in <a href="./homework.html">Week 12 Homework — Milestone 1: a walking skeleton</a>.</p><ul><li><strong>Core (Milestone 1):</strong> the Goldfish test and revision; the <strong>AGENTS.md trial</strong>; one more feature as a pull request, test first; production URL and screenshot; <code>PROMPTS.md</code> with teach-backs. Plus a reflection on Canvas.</li><li><strong>Stretch:</strong> add an MCP server after reading it; compare a second agent on the same task.</li></ul><p>Counts in <a href="./../../assessment/rubrics.html#assignments">Assignments</a>, graded on completion and effort: Milestone 1 is this week&#39;s homework. The capstone has its own <a href="./../../assessment/rubrics.html#capstone">rubric</a>.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>GitHub&#39;s pull request page won&#39;t load</td><td>Keep working and committing on your branch; open the pull request when it&#39;s back</td></tr><tr><td>The test workflow doesn&#39;t run on the pull request</td><td>Check the <strong>Actions</strong> tab. If Actions is down, run <code>npm test</code> yourself, paste the summary into the description, and merge</td></tr><tr><td>Copilot credits ran out</td><td>Switch to the fallback agent in the <a href="./../../TOOLS.html">Tool Handout</a>, or build the clinic feature with Ask mode&#39;s advice; both count. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr><tr><td>The public API for Station D is down</td><td>Your tests use a fake <code>fetch</code>, so they still run. Build against the fake today; try the real service later</td></tr><tr><td>No partner for the planted-bug hunt</td><td>The lab has a &quot;Working alone?&quot; option</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>GitHub Docs, <a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/proposing-changes-to-your-work-with-pull-requests/about-pull-requests" target="_blank" rel="noreferrer">About pull requests</a>.</li><li>The <a href="https://agents.md/" target="_blank" rel="noreferrer">AGENTS.md</a> open format, with examples from real projects.</li><li>Simon Willison, <a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Agentic Engineering Patterns</a>.</li><li>More readings: the <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',40)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
